const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Geometry & Time Definitions
  const reservoir = ee.Geometry.Point([-107.1847, 33.1494]).buffer(5000); // Elephant Butte Reservoir, NM

  // Date ranges (±15 days for cloud-free composite)
  const date1986 = ee.Date('1986-06-12');
  const date2020 = ee.Date('2020-06-09');
  const range15days = 15 * 24 * 60 * 60 * 1000; // 15 days in milliseconds

  // 2. Data Acquisition - Landsat 5 for 1986, Landsat 8 for 2020
  const landsat5 = ee.ImageCollection('LANDSAT/LT05/C02/T1_L2')
    .filterBounds(reservoir)
    .filterDate(date1986.advance(-range15days, 'milliseconds'), date1986.advance(range15days, 'milliseconds'))
    .filter(ee.Filter.lt('CLOUD_COVER', 20));

  const landsat8 = ee.ImageCollection('LANDSAT/LC08/C02/T1_L2')
    .filterBounds(reservoir)
    .filterDate(date2020.advance(-range15days, 'milliseconds'), date2020.advance(range15days, 'milliseconds'))
    .filter(ee.Filter.lt('CLOUD_COVER', 20));

  // Check collection sizes
  const count1986 = landsat5.size().getInfo();
  const count2020 = landsat8.size().getInfo();

  console.log(`1986 Images: ${count1986}, 2020 Images: ${count2020}`);

  if (count1986 === 0 || count2020 === 0) {
    console.log("<answer>C1</answer>");
    return;
  }

  // Get median composites
  const img1986 = landsat5.median().clip(reservoir);
  const img2020 = landsat8.median().clip(reservoir);

  // 3. Water Detection using NDWI
  function calculateNDWI(img) {
    // For Landsat 5: Green = B2, NIR = B4
    // For Landsat 8: Green = B3, NIR = B5
    const green = img.select('SR_B2'); // Both use same band names in C2 collection
    const nir = img.select('SR_B4');
    return green.subtract(nir).divide(green.add(nir)).rename('NDWI');
  }

  const ndwi1986 = calculateNDWI(img1986);
  const ndwi2020 = calculateNDWI(img2020);

  // Water mask (NDWI > 0 threshold)
  const water1986 = ndwi1986.gt(0);
  const water2020 = ndwi2020.gt(0);

  // 4. Calculate water areas
  const scale = 30; // Landsat resolution

  const area1986 = water1986.reduceRegion({
    reducer: ee.Reducer.sum(),
    geometry: reservoir,
    scale: scale,
    maxPixels: 1e9
  }).get('NDWI').getInfo();

  const area2020 = water2020.reduceRegion({
    reducer: ee.Reducer.sum(),
    geometry: reservoir,
    scale: scale,
    maxPixels: 1e9
  }).get('NDWI').getInfo();

  // Count valid pixels to check for C2
  const count1986Pixels = water1986.reduceRegion({
    reducer: ee.Reducer.count(),
    geometry: reservoir,
    scale: scale,
    maxPixels: 1e9
  }).get('NDWI').getInfo();

  const count2020Pixels = water2020.reduceRegion({
    reducer: ee.Reducer.count(),
    geometry: reservoir,
    scale: scale,
    maxPixels: 1e9
  }).get('NDWI').getInfo();

  console.log(`1986 Water Pixels: ${area1986}, Total Pixels: ${count1986Pixels}`);
  console.log(`2020 Water Pixels: ${area2020}, Total Pixels: ${count2020Pixels}`);

  // Check for no valid pixels
  if (count1986Pixels === 0 || count2020Pixels === 0) {
    console.log("<answer>C2</answer>");
    return;
  }

  // Check for calculation failure
  if (area1986 === null || area2020 === null || isNaN(area1986) || isNaN(area2020)) {
    console.log("<answer>C3</answer>");
    return;
  }

  // 5. Final comparison
  const decreasePercent = ((area1986 - area2020) / area1986 * 100).toFixed(1);
  console.log(`Water extent change: ${decreasePercent}%`);

  if (area2020 < area1986) {
    console.log("<answer>A</answer>");
  } else {
    console.log("<answer>B</answer>");
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
